#define MAXN 100

int n;
double prob[MAXN];
int graph[MAXN][MAXN];
int deg[MAXN];
double dp[MAXN];
int visited[MAXN];

void dfs(int u) {
    visited[u] = 1;
    double res = 1.0;
    for (int i = 0; i < deg[u]; i++) {
        int v = graph[u][i];
        if (!visited[v]) {
