#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 1000
#define MAXM 200000

typedef struct {
    int to, next;
} Edge;

static Edge edges[MAXM];
static int head[MAXN], indeg[MAXN];
static int edge_cnt;

static int dfn[MAXN], low[MAXN], in_stack[MAXN], stk[MAXN], top_stk;
static int comp[MAXN], comp_cnt, timer_;

static int comp_size[MAXN];
static int comp_indeg[MAXN];
static double p_sleep[MAXN];
static double comp_all_sleep[MAXN];

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void tarjan(int u) {
    dfn[u] = low[u] = ++timer_;
    stk[top_stk++] = u;
    in_stack[u] = 1;

    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (!dfn[v]) {
            tarjan(v);
            if (low[v] < low[u]) low[u] = low[v];
        } else if (in_stack[v] && dfn[v] < low[u]) {
            low[u] = dfn[v];
        }
    }

    if (low[u] == dfn[u]) {
        while (1) {
            int v = stk[--top_stk];
            in_stack[v] = 0;
            comp[v] = comp_cnt;
            if (v == u) break;
        }
        comp_cnt++;
    }
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        for (int i = 0; i < n; i++) head[i] = -1;
        edge_cnt = 0;

        for (int i = 0; i < n; i++) {
            int k;
            scanf("%lf %d", &p_sleep[i], &k);
            for (int j = 0; j < k; j++) {
                int x;
                scanf("%d", &x);
                x--; /* assume input is 1-based */
                add_edge(i, x);
            }
        }

        memset(dfn, 0, sizeof(int) * n);
        memset(low, 0, sizeof(int) * n);
        memset(in_stack, 0, sizeof(int) * n);
        top_stk = 0;
        comp_cnt = 0;
        timer_ = 0;

        for (int i = 0; i < n; i++) {
            if (!dfn[i]) tarjan(i);
        }

        for (int i = 0; i < comp_cnt; i++) {
            comp_size[i] = 0;
            comp_indeg[i] = 0;
            comp_all_sleep[i] = 1.0;
        }

        for (int i = 0; i < n; i++) {
            int c = comp[i];
            comp_size[c]++;
            comp_all_sleep[c] *= p_sleep[i];
        }

        for (int u = 0; u < n; u++) {
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (comp[u] != comp[v]) {
                    comp_indeg[comp[v]]++;
                }
            }
        }

        double ans = 1.0;
        for (int c = 0; c < comp_cnt; c++) {
            if (comp_indeg[c] == 0) {
                ans *= (1.0 - comp_all_sleep[c]);
            }
        }

        printf("%.6f\n", ans);
    }
    return 0;
}

