                }
            }

            double result = 1.0;
            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    result *= dfs(i);
                }
            }
            System.out.printf("%.2f%n", result);
        }
        sc.close();
    }

    static double dfs(int u) {
        visited[u] = true;
        double wakeProb = prob[u];
        double selfOversleep = 1.0 - prob[u];
        double callWakeProb = 1.0;

        for (int v : graph[u]) {
            if (!visited[v]) {
                callWakeProb *= (1.0 - dfs(v));
            }
        }

        return 1.0 - selfOversleep * callWakeProb;
    }
