        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;

            double[] p = new double[n];
            int[][] contacts = new int[n][];

            for (int i = 0; i < n; i++) {
                p[i] = sc.nextDouble();
                int k = sc.nextInt();
                contacts[i] = new int[k];
                for (int j = 0; j < k; j++) {
                    contacts[i][j] = sc.nextInt() - 1; // 0-indexed
                }
            }

            double prob = 0.0;

            for (int mask = 0; mask < (1 << n); mask++) {
                // mask: bit i set means person i would oversleep naturally
                double pr = 1.0;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) pr *= p[i];
                    else pr *= (1 - p[i]);
                }

                // Simulate wake-up calls
                boolean[] awake = new boolean[n];
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) == 0) awake[i] = true;
                }

                // BFS/propagation
                boolean changed = true;
                while (changed) {
                    changed = false;
                    for (int i = 0; i < n; i++) {
                        if (awake[i]) {
                            for (int c : contacts[i]) {
                                if (!awake[c]) {
                                    awake[c] = true;
                                    changed = true;
                                }
                            }
                        }
                    }
                }

                // Check if all awake
                boolean allAwake = true;
                for (int i = 0; i < n; i++) {
                    if (!awake[i]) { allAwake = false; break; }
                }

                if (allAwake) prob += pr;
            }

            System.out.printf("%.4f%n", prob);
